            ...row,
            deleted_at: m.deleted_at || new Date().toISOString(),
            content: '',
            file_url: '',
            file_name: '',
            file_size: 0,
            thumb_b64: null,
            hls_url: null,
            waveform: null,
            deleted_by: m.deleted_by || '',
